Context: fill loop hands a capped validator's surplus to the smallest validators
```
// Before:
    while used < seat_count {
        let before = used;
        for (_, _, index) in &remainders {
            if used == seat_count {
                break;
            }
            if alloc[*index] < cap {
                alloc[*index] += 1;
