            // A leftover seat may only go to a validator that is still below
            // its exact proportional share. Handing a capped validator's
            // surplus to the smallest ones gave a validator with a negligible
            // weight a quarter of the seats, which is not the proportional
            // allocation this table promises.
            let ideal = seats * u128::from(members[*index].1);
            let held = u128::try_from(alloc[*index]).unwrap_or(0) * total_weight;
            if alloc[*index] < cap && held < ideal {
                alloc[*index] += 1;
                used += 1;
