    fun unwrapKey(envelope: WrappedKeyEnvelope, authenticatedCipher: Cipher? = null): ByteArray {
        require(envelope.keystoreAlias == aliasFor(envelope.purpose)) {
            "wrapping key alias does not match the key purpose"
        }
        val cipher = if (envelope.purpose.requiresBiometricOrPin) {
            // The owner wrapping key is authentication-bound: only the cipher returned by
