// After:
    /// Raise the bundle's verification level from a chain-side attestation.
    /// Never alters sentence prose.
    ///
    /// # Errors
    ///
    /// Refuses an attestation that does not cover this bundle's prose digest,
    /// and returns [`ApbError::LevelTransition`] on any attempt to lower the
    /// level.
    pub fn upgrade_level(&mut self, attestation: &LevelAttestation) -> Result<(), ApbError> {
        if attestation.prose_digest != self.prose_digest {
            return Err(ApbError::LevelUnbound);
        }
        self.verification_level
            .raise(attestation.level)
            .map_err(ApbError::LevelTransition)
    }
